package com.luminor.tavernquest.data.local.preferences
import android.content.Context;import androidx.datastore.preferences.core.edit;import com.luminor.tavernquest.domain.repository.GameSettings;import kotlinx.coroutines.flow.*
class SettingsDataSource(private val context:Context){val settings=context.tavernDataStore.data.map{GameSettings(it[PreferenceKeys.ONBOARDING]?:false,it[PreferenceKeys.SOUND]?:true,it[PreferenceKeys.HAPTICS]?:true,it[PreferenceKeys.TAB]?:"tavern")};suspend fun onboarding(v:Boolean)=context.tavernDataStore.edit{it[PreferenceKeys.ONBOARDING]=v};suspend fun sound(v:Boolean)=context.tavernDataStore.edit{it[PreferenceKeys.SOUND]=v};suspend fun haptics(v:Boolean)=context.tavernDataStore.edit{it[PreferenceKeys.HAPTICS]=v};suspend fun reset()=context.tavernDataStore.edit{it.clear()}}
